window.LEGACY_CARD_MAP={};
for(const l of window.LESSONS){l.cards=[];for(const oldId of window.LEGACY_GROUPS[l.id]){const old=window.ORIGINAL_LESSONS.find(x=>x.id===oldId);old.cards.forEach((card,i)=>{window.LEGACY_CARD_MAP[oldId+'-'+i]=l.id+'-'+l.cards.length;l.cards.push(card);});}}
